generated_pydough:
rock_tracks_count = GRAPH.CALCULATE(
    number_of_rock_tracks=COUNT(tracks.WHERE(track.genre.name == "Rock").trackid)
)

# 1. Get the distinct chip_model names that are currently used by any phone.
#    The 'chip_model' column in the 'phones' collection stores the model name of the chip used.
used_chip_model_names = phones.CALCULATE(
    used_model_name=phones.chip_model # Select the chip_model column and alias it
).PARTITION(
    name="distinct_used_models_partition", # Create a partition to get distinct used model names
    by=used_model_name           # Group by 'used_model_name' to get unique values
).CALCULATE(
    used_model_name              # Select the distinct used model names from the partition
)

# 2. Filter 'chip_models' where their 'Model_name' is NOT present in the list of 'used_model_name's.
# 3. Calculate the average 'RAM_MiB' for these filtered (unused) chip models at the graph level.
avg_ram_mib_unused_chips = GRAPH.CALCULATE(
    avg_ram_mib=AVG(
        chip_models.WHERE(
            chip_models.Model_name.NOT_IN(used_chip_model_names.used_model_name)
        ).RAM_MiB
    )
)

