# Step 1: Get the classrooms associated with 'MADLOCK RAY' from the lists collection.
# Use correct casing for column names (lastname, firstname, classroom) as per schema.
madlock_ray_classroom_ids = student_1.lists.WHERE(
    (lastname == 'MADLOCK') & (firstname == 'RAY')
).CALCULATE(
    student_classroom_id=classroom
)

# Step 2: Count the total number of teachers found in the identified classrooms.
# Perform the count from the top-level 'student_1' context to ensure a result
# (even 0) is always returned. Use DEFAULT_TO to ensure a 0 is returned if COUNT yields no value.
result = student_1.CALCULATE(
    num_teachers=DEFAULT_TO(
        COUNT(
            student_1.teacher.WHERE(
                ISIN(classroom, madlock_ray_classroom_ids.student_classroom_id)
            )
        ),
        0
    )
)

