# Step 1: Safely retrieve the classroom ID for LORIA ONDERSMA.
# If the teacher does not exist, MAX(collection.attribute) will return NULL,
# which DEFAULT_TO will convert to -1 (a non-matching classroom ID).
loria_classroom_id_safe = DEFAULT_TO(
    MAX(
        teacher.WHERE(
            (firstname == "LORIA") & (lastname == "ONDERSMA")
        ).CALCULATE(
            teacher_classroom_id = classroom
        ).teacher_classroom_id
    ),
    -1
)

# Step 2: Count the number of students in the identified classroom.
# Using DEFAULT_TO with COUNT ensures a 0 is returned if no students are found,
# and GRAPH.CALCULATE ensures a single result row.
result = GRAPH.CALCULATE(
    num_students = DEFAULT_TO(
        COUNT(
            lists.WHERE(
                classroom == loria_classroom_id_safe
            )
        ),
        0
    )
)

