    1, by=price_in_dollars.DESC()
).CALCULATE(
    entry_name=catalog_entry_name
)

max_mpg_result = GRAPH.CALCULATE(
    max_mpg=MAX(
        cars_datas.WHERE(
            (cylinders == 8) | (year < 1980)
        ).CALCULATE(
            numeric_mpg=DECIMAL(mpg)
        ).numeric_mpg
    )
)

stations_with_max_available = stations.CALCULATE(
    max_available=MAX(statuses.bikes_available)
)

filtered_stations = stations_with_max_available.WHERE(
    max_available <= 10
)

mean_longitude = GRAPH.CALCULATE(
    mean_longitude=AVG(filtered_stations.long)
)

total_enrollment_no_goalie_players = colleges.PARTITION(name="college_groups", by=cname).CALCULATE(
    college_cname=cname,
    college_enr=enr,
    has_goalie_player=HAS(colleges.tryouts.WHERE(tryouts.ppos == 'goalie'))
).WHERE(
    ~has_goalie_player
).CALCULATE(
    total_enrollment=SUM(college_enr)
)

result = GRAPH.CALCULATE(
    total_unique_official_languages=NDISTINCT(
        countries.WHERE(
            (IndepYear < 1930) & HAS(countrylanguages) == 1
        ).countrylanguages.WHERE(
            IsOfficial == 'T'
        ).Language
    )
)

song_vocals = song.WHERE(
    title == "Badlands"
).vocal.PARTITION(
    name="distinct_vocals",
    by=type
).CALCULATE(
    TYPE=type
)

result = airport.WHERE(
    HASNOT(flight) & (COUNT(flight.WHERE(destairport == airportcode)) == 0)
).CALCULATE(
    airportname=airportname,
    airportcode=airportcode
)

most_prolific_publisher = Catalogs.PARTITION(
    name="publisher_groups", by=(catalog_publisher)
).CALCULATE(
    catalog_publisher=catalog_publisher,
    num_catalogs=COUNT(catalog_id)
).TOP_K(1, by=num_catalogs.DESC()
).CALCULATE(
    catalog_publisher=catalog_publisher
)

filtered_cities_temps = temperature.WHERE(
    (Mar < Jul) | (Mar > Oct)
).CALCULATE(
    city_name=city.City
)

committees_with_party_delegates = elections.PARTITION(name="committee_groups", by=committee).CALCULATE(
    committee_name=committee,
    has_democratic_delegate=HAS(elections.WHERE(party == 'Democratic')) == 1,
    has_liberal_delegate=HAS(elections.WHERE(party == 'Liberal')) == 1
).WHERE(
    (has_democratic_delegate == True) & (has_liberal_delegate == True)
).CALCULATE(
    committee_name=committee_name
)

most_languages_continent = countries.PARTITION(
    name="continent_groups", by=(continent)
).CALCULATE(
    continent_name=continent,
    num_languages=NDISTINCT(countries.countrylanguages.language)
).TOP_K(1, by=num_languages.DESC())

makers_with_multiple_models = car_maker.CALCULATE(
    maker_fullname=fullname,
    maker_id=id,
    num_models=COUNT(model_lists.modelid)
).WHERE(
    num_models > 3
).CALCULATE(
    fullname=maker_fullname,
    id=maker_id
)

result = vocal.WHERE(
    (vocal.band.firstname == "Solveig") &
    (vocal.song.title == "A Bar in Amsterdam")
).CALCULATE(
    vocal_type=type
)

advisors_with_spring_treasurer_votes = students.JOIN(
    voting_records,
    students.stuid == voting_records.treasurer_vote
).WHERE(
    voting_records.election_cycle == 'Spring'
).CALCULATE(
    advisor_id=students.advisor
).DISTINCT()

total_degrees_per_campus = Campuses.CALCULATE(
    campus_name=Campus, # Select the campus name (using correct casing from schema)
    total_degrees_granted=SUM( # Calculate the sum of degrees for each campus
        degrees.WHERE( # Access the 'degrees' sub-collection (using correct plural and casing)
            (Year >= 1998) & (Year <= 2002) # Filter degree records by year range (using correct casing for Year)
        ).Degrees # Access the 'Degrees' column from the filtered sub-collection (using correct casing)
    )
)

total_citations_p_2005 = academic.publications.WHERE(
    (academic.publications.journal.name == "PVLDB") & 
    (academic.publications.year == 2005)
).CALCULATE(
    total_citations=SUM(citation_num)
)

ships_without_captains_data = ships.WHERE(
    HASNOT(captains) == 1
).CALCULATE(
    ship_name=name,
    ship_class=class
)

most_frequent_crime_time = GreaterManchesterCrime.PARTITION(
    name="crime_timestamps_group", by=GreaterManchesterCrime.CrimeTS
).CALCULATE(
    crime_timestamp=GreaterManchesterCrime.CrimeTS,
    num_crimes=COUNT(GreaterManchesterCrime)
).TOP_K(1, by=num_crimes.DESC()).CALCULATE(
    CrimeTS=crime_timestamp
)

investigation_complete_cases = GreaterManchesterCrime.WHERE(
    outcome == 'Investigation complete; no suspect identified'
)

crime_counts_by_type = investigation_complete_cases.PARTITION(
    name="crime_types_group", by=(type)
).CALCULATE(
    crime_type=type,
    num_complete_cases=COUNT() # Corrected to count within the current partition
)

most_common_crime_type = crime_counts_by_type.TOP_K(1, by=num_complete_cases.DESC())
